pub fn dev_transition(env: &Env, st: &DevState, cmd: &DevCmd) -> (Option<DevState>, Outcome) {
    match cmd {
        DevCmd::ReadSettings => (None, Outcome::Read),
        DevCmd::ReadRgb => (None, Outcome::Read),
        DevCmd::WriteSettings { spool } => {
            (Some(DevState { spool: *spool, reset_pending: st.reset_pending }), Outcome::Persist(Key::Settings))
        }
        DevCmd::WriteRgb => (None, Outcome::Persist(Key::Rgb)),
        DevCmd::WriteWifi => {
            (Some(DevState { spool: st.spool, reset_pending: true }), Outcome::PersistThenReset(Key::Wifi))
        }
        DevCmd::ReadInfo => {
            if env.info_ready { (None, Outcome::Read) } else { (None, Outcome::Refuse(NOT_READY)) }
        }
        DevCmd::Calibrate => {
            if env.client_connected { (None, Outcome::Forward) } else { (None, Outcome::Refuse(NO_CLIENT)) }
        }
        DevCmd::GetFilaments => {
            if spool_usable(st.spool) { (None, Outcome::Forward) } else { (None, Outcome::Refuse(NOT_CONFIGURED)) }
        }
        DevCmd::SetFilament => {
            if spool_usable(st.spool) { (None, Outcome::Forward) } else { (None, Outcome::Refuse(NOT_CONFIGURED)) }
        }
    }
}

